test:
data = {'a.txt': b'cat', 'b.txt': b'dog!', 'c.txt': b'cat', 'd.txt': b'bird', 'e.txt': b'xx', 'f.txt': b'xx'}
files = [(path, len(content)) for path, content in data.items()]
def read_file(path):
    return data[path]
assert find_duplicate_files(files, read_file) == [['a.txt', 'c.txt'], ['e.txt', 'f.txt']]

data = {'a': b'', 'b': b'', 'c': b''}
files = [(path, 0) for path in data]
def read_file(path):
    return data[path]
assert find_duplicate_files(files, read_file) == [['a', 'b', 'c']]

data = {'a': b'ab', 'b': b'cd', 'c': b'ab'}
files = [(path, 2) for path in data]
def read_file(path):
    return data[path]
assert find_duplicate_files(files, read_file) == [['a', 'c']]
